223	
224	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
225	    @Override
226	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
227	        HttpHeaders headers = new HttpHeaders();
228	        Visit visit = visitMapper.toVisit(visitFieldsDto);
229	        Pet pet = new Pet();
230	        pet.setId(petId);
231	        visit.setPet(pet);
232	        this.clinicService.saveVisit(visit);
233	        VisitDto visitDto = visitMapper.toVisitDto(visit);
